/**
 * Checks if there is a unary successor operator under given index.
 */
public function isUnarySuccessorOperator(int $index): bool
{
    static $allowedPrevToken = [
        ']',
        [T_STRING],
        [T_VARIABLE],
        [CT::T_ARRAY_INDEX_CURLY_BRACE_CLOSE],
        [CT::T_DYNAMIC_PROP_BRACE_CLOSE],
        [CT::T_DYNAMIC_VAR_BRACE_CLOSE],
    ];

    $tokens = $this->tokens;
    $token = $tokens[$index];

    if (!$token->isGivenKind([T_INC, T_DEC])) {
        return false;
    }

    $prevToken = $tokens[$tokens->getPrevMeaningfulToken($index)];

    return $prevToken->equalsAny($allowedPrevToken);
}

/**
 * Checks if there is a binary operator under given index.
 */
public function isBinaryOperator(int $index): bool
{
    static $nonArrayOperators = [
        '=' => true,
        '*' => true,
        '/' => true,
        '%' => true,
        '<' => true,
        '>' => true,
        '|' => true,
        '^' => true,
        '.' => true,
    ];

    static $potentialUnaryNonArrayOperators = [
        '+' => true,
        '-' => true,
        '&' => true,
    ];

    static $arrayOperators;

    if (null === $arrayOperators) {
        $arrayOperators = [
            T_AND_EQUAL => true,            // &=
            T_BOOLEAN_AND => true,          // &&
            T_BOOLEAN_OR => true,           // ||
            T_CONCAT_EQUAL => true,         // .=
            T_DIV_EQUAL => true,            // /=
            T_DOUBLE_ARROW => true,         // =>
            T_IS_EQUAL => true,             // ==
            T_IS_GREATER_OR_EQUAL => true,  // >=
            T_IS_IDENTICAL => true,         // ===
            T_IS_NOT_EQUAL => true,         // !=, <>
            T_IS_NOT_IDENTICAL => true,     // !==
            T_IS_SMALLER_OR_EQUAL => true,  // <=
            T_LOGICAL_AND => true,          // and
            T_LOGICAL_OR => true,           // or
            T_LOGICAL_XOR => true,          // xor
            T_MINUS_EQUAL => true,          // -=
            T_MOD_EQUAL => true,            // %=
            T_MUL_EQUAL => true,            // *=
            T_OR_EQUAL => true,             // |=
            T_PLUS_EQUAL => true,           // +=
            T_POW => true,                  // **
            T_POW_EQUAL => true,            // **=
            T_SL => true,                   // <<
            T_SL_EQUAL => true,             // <<=
            T_SR => true,                   // >>
            T_SR_EQUAL => true,             // >>=
            T_XOR_EQUAL => true,            // ^=
            T_SPACESHIP => true,            // <=>
            T_COALESCE => true,             // ??
            T_COALESCE_EQUAL => true,       // ??=
        ];
    }

    $tokens = $this->tokens;
    $token = $tokens[$index];

    if ($token->isGivenKind([T_INLINE_HTML, T_ENCAPSED_AND_WHITESPACE, CT::T_TYPE_INTERSECTION])) {
        return false;
    }

    if (isset($potentialUnaryNonArrayOperators[$token->getContent()])) {
        if (null === $this->binaryOperatorSpacesFixer) {
            $this->binaryOperatorSpacesFixer = new BinaryOperatorSpacesFixer();
        }

        return !$this->binaryOperatorSpacesFixer->isUnaryPredecessorOperator($this->tokens, $index);
    }

    if ($token->isArray()) {
        return isset($arrayOperators[$token->getId()]);
    }

    if (isset($nonArrayOperators[$token->getContent()])) {
        return true;
    }

    return false;
}

